/**
 * Logger - 日志工具
 */

const fs = require('fs');
const path = require('path');

/**
 * 日志级别
 */
const LogLevel = {
  DEBUG: 0,
  INFO: 1,
  WARN: 2,
  ERROR: 3
};

/**
 * 日志级别名称
 */
const LogLevelNames = {
  0: 'DEBUG',
  1: 'INFO',
  2: 'WARN',
  3: 'ERROR'
};

/**
 * 创建日志记录器
 */
function createLogger(options = {}) {
  const level = options.level || 'INFO';
  const logLevel = LogLevel[level] || LogLevel.INFO;
  const logFile = options.file || null;
  
  // 确保日志目录存在
  if (logFile) {
    const logDir = path.dirname(logFile);
    if (!fs.existsSync(logDir)) {
      fs.mkdirSync(logDir, { recursive: true });
    }
  }
  
  /**
   * 格式化日志消息
   */
  function formatMessage(level, message, meta = {}) {
    const timestamp = new Date().toISOString();
    const levelName = LogLevelNames[level];
    const metaStr = Object.keys(meta).length > 0 ? JSON.stringify(meta) : '';
    
    return `[${timestamp}] [${levelName}] ${message}${metaStr ? ' ' + metaStr : ''}`;
  }
  
  /**
   * 写入日志文件
   */
  function writeToFile(message) {
    if (!logFile) return;
    
    try {
      fs.appendFileSync(logFile, message + '\n');
    } catch (error) {
      console.error('Failed to write log file:', error.message);
    }
  }
  
  /**
   * 输出日志
   */
  function log(level, message, meta = {}) {
    if (level < logLevel) return;
    
    const formatted = formatMessage(level, message, meta);
    
    // 控制台输出
    switch (level) {
      case LogLevel.DEBUG:
        console.debug(formatted);
        break;
      case LogLevel.INFO:
        console.log(formatted);
        break;
      case LogLevel.WARN:
        console.warn(formatted);
        break;
      case LogLevel.ERROR:
        console.error(formatted);
        break;
    }
    
    // 文件输出
    writeToFile(formatted);
  }
  
  return {
    debug: (message, meta) => log(LogLevel.DEBUG, message, meta),
    info: (message, meta) => log(LogLevel.INFO, message, meta),
    warn: (message, meta) => log(LogLevel.WARN, message, meta),
    error: (message, meta) => log(LogLevel.ERROR, message, meta),
    setLevel: (newLevel) => {
      // 重新创建 logger
      return createLogger({ ...options, level: newLevel });
    }
  };
}

// 默认日志记录器
const defaultLogger = createLogger();

module.exports = {
  LogLevel,
  LogLevelNames,
  createLogger,
  defaultLogger
};
